 public class RestartPlan {
  public string Proxy {get;set;} public string DueUtc {get;set;} public string DeferredUntilUtc {get;set;} public bool ForceRequired {get;set;} public int Ticket {get;set;}
  public RestartPlan(){Proxy="";DueUtc="";DeferredUntilUtc="";}
  public void Queue(string proxy,DateTime now,int notice){if(Proxy==proxy&&!String.IsNullOrEmpty(DueUtc))return;Proxy=proxy;DateTime due=now.AddSeconds(notice),deferred=Files.Date(DeferredUntilUtc);if(deferred>due)due=deferred;DueUtc=due.ToString("o");ForceRequired=false;Ticket++;}
  public void Delay(DateTime now){DeferredUntilUtc=now.AddMinutes(10).ToString("o");DueUtc=DeferredUntilUtc;ForceRequired=false;}
  public void Resume(DateTime now,int notice){if(String.IsNullOrEmpty(Proxy))return;DateTime due=now.AddSeconds(notice),deferred=Files.Date(DeferredUntilUtc);if(deferred>due)due=deferred;DueUtc=due.ToString("o");Ticket++;}
  public bool Ready(DateTime now){return !String.IsNullOrEmpty(Proxy)&&now>=Files.Date(DueUtc)&&!ForceRequired;}
  public void Clear(){Proxy="";DueUtc="";DeferredUntilUtc="";ForceRequired=false;}
 }
