 static class Files {
  public static readonly object Gate=new object();
  public static T Load<T>(string name) where T:new(){lock(Gate){string path=Path.Combine(Program.Root,name);return File.Exists(path)?new JavaScriptSerializer().Deserialize<T>(File.ReadAllText(path)):new T();}}
  public static void Save(string name,object value){lock(Gate){string path=Path.Combine(Program.Root,name),tmp=path+".tmp";File.WriteAllText(tmp,new JavaScriptSerializer().Serialize(value),new UTF8Encoding(false));if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}}
  public static DateTime Date(string value){DateTime date;return DateTime.TryParse(value,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out date)?date.ToUniversalTime():DateTime.MinValue;}
  public static void Log(string message){lock(Gate){try{string path=Path.Combine(Program.Root,"guard.log");if(File.Exists(path)&&new FileInfo(path).Length>1024*1024){var lines=File.ReadAllLines(path);File.WriteAllLines(path,lines.Skip(Math.Max(0,lines.Length-2000)).ToArray(),new UTF8Encoding(false));}File.AppendAllText(path,DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+"  "+message+Environment.NewLine,new UTF8Encoding(false));}catch{}}}
 }
