 public static class ProxyTools {
  public static string Normalize(string value){if(String.IsNullOrWhiteSpace(value))return null;string text=value.Trim();if(!text.Contains("://"))text="http://"+text;Uri u;if(!Uri.TryCreate(text,UriKind.Absolute,out u)||u.Scheme!="http"||u.Port<1||u.Port>65535||!String.IsNullOrEmpty(u.UserInfo)||u.AbsolutePath!="/"||!String.IsNullOrEmpty(u.Query)||!String.IsNullOrEmpty(u.Fragment))return null;string host=u.Host;if(u.HostNameType==UriHostNameType.IPv6)host="["+IPAddress.Parse(host.Trim('[',']')).ToString()+"]";return "http://"+host+":"+u.Port;}
  static bool Open(TcpClient client,Uri uri){var a=client.BeginConnect(uri.Host.Trim('[',']'),uri.Port,null,null);try{if(!a.AsyncWaitHandle.WaitOne(1500))return false;client.EndConnect(a);return true;}finally{a.AsyncWaitHandle.Close();}}
  public static bool Tcp(string uri){using(var client=new TcpClient()){try{return Open(client,new Uri(uri));}catch{return false;}}}
  public static bool Connect(string uri){using(var client=new TcpClient()){try{if(!Open(client,new Uri(uri)))return false;var stream=client.GetStream();stream.ReadTimeout=4000;stream.WriteTimeout=2000;byte[] data=Encoding.ASCII.GetBytes("CONNECT chatgpt.com:443 HTTP/1.1\r\nHost: chatgpt.com:443\r\nProxy-Connection: close\r\n\r\n");stream.Write(data,0,data.Length);var line=new StringBuilder();while(line.Length<512){int n=stream.ReadByte();if(n<0)return false;if(n==10)break;line.Append((char)n);}string text=line.ToString();return text.StartsWith("HTTP/1.1 200 ",StringComparison.Ordinal)||text.StartsWith("HTTP/1.0 200 ",StringComparison.Ordinal);}catch{return false;}}}
  public static EndpointHealth Https(string proxy,string name,string target){var result=new EndpointHealth{Name=name,Detail="未检查"};HttpWebRequest request=null;try{request=(HttpWebRequest)WebRequest.Create(target);request.Method="HEAD";request.Timeout=6000;request.ReadWriteTimeout=6000;request.AllowAutoRedirect=false;request.UseDefaultCredentials=false;request.Proxy=proxy==null?null:new WebProxy(proxy);request.KeepAlive=false;using(var response=(HttpWebResponse)request.GetResponse()){result.Reachable=true;result.HttpStatus=(int)response.StatusCode;result.Detail="HTTPS 可达";}}catch(WebException e){var response=e.Response as HttpWebResponse;if(response!=null){using(response){result.HttpStatus=(int)response.StatusCode;result.Reachable=result.HttpStatus!=407;result.Detail=result.Reachable?"HTTPS 可达，匿名请求返回 HTTP "+result.HttpStatus:"代理要求认证";}}else result.Detail=e.Status==WebExceptionStatus.Timeout?"连接超时":e.Status==WebExceptionStatus.TrustFailure||e.Status==WebExceptionStatus.SecureChannelFailure?"TLS / 证书验证失败":"网络连接失败（"+e.Status+"）";}catch(Exception){result.Detail="HTTPS 检查失败";}finally{if(request!=null)request.Abort();}return result;}
  public static Health Probe(string uri){var health=new Health{CheckedUtc=DateTime.UtcNow.ToString("o"),Tcp=Tcp(uri)};if(!health.Tcp)return health;health.Tunnel=Connect(uri);if(!health.Tunnel)return health;health.Endpoints.Add(Https(uri,"ChatGPT","https://chatgpt.com/"));health.Endpoints.Add(Https(uri,"Codex","https://codex-cloud-environments.chatgpt.com/"));return health;}
  public static ProcessStartInfo StartInfo(string exe,string uri,bool minimized){var info=new ProcessStartInfo(exe){WorkingDirectory=Path.GetDirectoryName(exe),UseShellExecute=false,Arguments="--proxy-server="+uri+" --proxy-bypass-list=\"localhost;127.0.0.1;[::1]\""};foreach(string key in new[]{"HTTP_PROXY","HTTPS_PROXY","ALL_PROXY","http_proxy","https_proxy","all_proxy"})info.EnvironmentVariables[key]=uri;foreach(string key in new[]{"NO_PROXY","no_proxy"})info.EnvironmentVariables[key]="localhost,127.0.0.1,::1";if(minimized)info.WindowStyle=ProcessWindowStyle.Minimized;return info;}
  public static string Stable(ref string pending,ref int count,string value,int required){if(String.IsNullOrEmpty(value)){pending="";count=0;return null;}if(pending==value)count=Math.Min(required,count+1);else{pending=value;count=1;}return count>=required?value:null;}
  internal static IEnumerable<Candidate> Candidates(Settings settings){
   if(!String.IsNullOrWhiteSpace(settings.ExplicitProxy)){string manual=Normalize(settings.ExplicitProxy);if(manual==null)throw new InvalidOperationException("指定代理无效，请使用 HTTP / mixed 代理地址。");yield return new Candidate(manual,"手动指定");yield break;}
   using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Internet Settings")){if(key!=null&&Convert.ToInt32(key.GetValue("ProxyEnable",0))==1){string text=Convert.ToString(key.GetValue("ProxyServer",""));if(text.Contains("=")){var map=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string part in text.Split(';')){int at=part.IndexOf('=');if(at>0)map[part.Substring(0,at).Trim()]=part.Substring(at+1).Trim();}foreach(string name in new[]{"https","http"})if(map.ContainsKey(name)){string uri=Normalize(map[name]);if(uri!=null)yield return new Candidate(uri,"系统代理");}}else{string uri=Normalize(text);if(uri!=null)yield return new Candidate(uri,"系统代理");}}}
   var owners=new HashSet<int>();using(var search=new ManagementObjectSearcher("SELECT ProcessId FROM Win32_Process WHERE Name='verge-mihomo.exe' OR Name='mihomo.exe' OR Name='clash.exe'"))using(var found=search.Get()){foreach(ManagementObject item in found)owners.Add(Convert.ToInt32(item["ProcessId"]));}if(owners.Count==0)yield break;
   var listeners=Native.Listeners(owners);foreach(string file in settings.ProxyConfigFiles??new string[0]){if(!File.Exists(file))continue;var ports=new Dictionary<string,int>();foreach(string line in File.ReadLines(file)){var m=System.Text.RegularExpressions.Regex.Match(line,@"^(mixed-port|port):\s*(\d+)\s*(?:#.*)?$");int port;if(m.Success&&Int32.TryParse(m.Groups[2].Value,out port)&&port>0&&port<=65535)ports[m.Groups[1].Value]=port;}foreach(string type in new[]{"mixed-port","port"})if(ports.ContainsKey(type))foreach(var item in listeners.Where(x=>x.Item2==ports[type])){string host=item.Item1=="0.0.0.0"?"127.0.0.1":item.Item1;string uri=Normalize(host+":"+item.Item2);if(uri!=null)yield return new Candidate(uri,"Clash 实际监听");}}
  }
 }
 static class Native {
  [DllImport("iphlpapi.dll")]static extern uint GetExtendedTcpTable(IntPtr table,ref int size,bool order,int family,int tableClass,uint reserved);
  [DllImport("user32.dll")]internal static extern bool SetForegroundWindow(IntPtr window);
  [DllImport("user32.dll")]internal static extern bool ShowWindow(IntPtr window,int command);
  [DllImport("advapi32.dll",SetLastError=true)]static extern bool GetTokenInformation(IntPtr token,int type,IntPtr buffer,int size,out int needed);
  public static string SessionKey(){string boot="";using(var query=new ManagementObjectSearcher("SELECT LastBootUpTime FROM Win32_OperatingSystem"))using(var items=query.Get()){foreach(ManagementObject item in items){boot=ManagementDateTimeConverter.ToDateTime(Convert.ToString(item["LastBootUpTime"])).ToUniversalTime().Ticks.ToString();break;}}if(String.IsNullOrEmpty(boot))throw new InvalidOperationException("无法读取系统启动会话。");using(var identity=WindowsIdentity.GetCurrent()){IntPtr memory=Marshal.AllocHGlobal(128);try{int needed;if(!GetTokenInformation(identity.Token,10,memory,128,out needed))throw new InvalidOperationException("无法读取当前登录会话。");uint low=unchecked((uint)Marshal.ReadInt32(memory,8));int high=Marshal.ReadInt32(memory,12);return identity.User.Value+":"+boot+":"+Process.GetCurrentProcess().SessionId+":"+high+":"+low;}finally{Marshal.FreeHGlobal(memory);}}}
  internal static List<Tuple<string,int>> Listeners(HashSet<int> owners){int size=0;GetExtendedTcpTable(IntPtr.Zero,ref size,false,2,3,0);var result=new List<Tuple<string,int>>();if(size<=0)return result;IntPtr memory=Marshal.AllocHGlobal(size);try{if(GetExtendedTcpTable(memory,ref size,false,2,3,0)!=0)return result;int count=Marshal.ReadInt32(memory);for(int i=0;i<count;i++){IntPtr row=IntPtr.Add(memory,4+24*i);if(Marshal.ReadInt32(row)!=2||!owners.Contains(Marshal.ReadInt32(row,20)))continue;byte[] port=BitConverter.GetBytes(Marshal.ReadInt32(row,8));result.Add(Tuple.Create(new IPAddress(BitConverter.GetBytes(unchecked((uint)Marshal.ReadInt32(row,4)))).ToString(),(port[0]<<8)|port[1]));}}finally{Marshal.FreeHGlobal(memory);}return result;}
  internal static List<RootProcess> Processes(){int session=Process.GetCurrentProcess().SessionId;var result=new List<RootProcess>();using(var search=new ManagementObjectSearcher("SELECT Name,ProcessId,ParentProcessId,ExecutablePath,CommandLine,SessionId FROM Win32_Process WHERE Name='ChatGPT.exe' OR Name='codex.exe' OR Name='codex-code-mode-host.exe' OR Name='codex-computer-use-swift.exe'"))using(var found=search.Get()){foreach(ManagementObject item in found){if(Convert.ToInt32(item["SessionId"])!=session)continue;int pid=Convert.ToInt32(item["ProcessId"]);try{using(var process=Process.GetProcessById(pid))result.Add(new RootProcess{Pid=pid,Parent=Convert.ToInt32(item["ParentProcessId"]),Name=Convert.ToString(item["Name"]),Path=Convert.ToString(item["ExecutablePath"]),Command=Convert.ToString(item["CommandLine"]),StartTicks=process.StartTime.ToUniversalTime().Ticks});}catch{}}}return result;}
  internal static List<RootProcess> Roots(){return Processes().Where(p=>p.Name=="ChatGPT.exe"&&System.Text.RegularExpressions.Regex.IsMatch(p.Path,@"\\WindowsApps\\OpenAI\.Codex_[^\\]+\\app\\ChatGPT\.exe$",System.Text.RegularExpressions.RegexOptions.IgnoreCase)&&!p.Command.Contains("--type=")).ToList();}
  internal static bool Identity(RootProcess p){try{using(var live=Process.GetProcessById(p.Pid))return live.StartTime.ToUniversalTime().Ticks==p.StartTicks;}catch{return false;}}
  internal static string CodexExe(){using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppModel\Repository\Packages")){if(key!=null){foreach(string name in key.GetSubKeyNames().Where(n=>n.StartsWith("OpenAI.Codex_",StringComparison.OrdinalIgnoreCase)).OrderByDescending(n=>VersionOf(n)))using(var package=key.OpenSubKey(name)){string root=Convert.ToString(package.GetValue("PackageRootFolder",""));if(!String.IsNullOrEmpty(root)){string path=Path.Combine(root,@"app\ChatGPT.exe");if(File.Exists(path))return path;}}}}throw new InvalidOperationException("未找到已安装的 Codex 桌面端。");}
  static Version VersionOf(string name){Version version;return Version.TryParse(name.Split('_')[1],out version)?version:new Version(0,0);}
 }
 sealed class Engine:IDisposable {
  readonly object gate=new object();Settings config;RuntimeState state;System.Threading.Timer timer;int busy,failures,samples;string pending="",lastMode="";DateTime next=DateTime.MinValue;volatile bool disposed,manualRestart,forceNow,openRequested,probeRequested;
  int healthBusy;readonly Dictionary<string,Health> cached=new Dictionary<string,Health>();public volatile ViewState View;
  public Engine(){config=Files.Load<Settings>("settings.json");state=Files.Load<RuntimeState>("state.json");if(state.Plan==null)state.Plan=new RestartPlan();if(state.RestartHistoryUtc==null)state.RestartHistoryUtc=new List<string>();View=new ViewState{Mode="启动中",Health=new Health(),ObservedProxy="",AppliedProxy=state.AppliedProxy,LastError="",RestartDueUtc=state.Plan.DueUtc};}
  public Settings Config(){lock(gate){return new JavaScriptSerializer().Deserialize<Settings>(new JavaScriptSerializer().Serialize(config));}}
  public void Update(Action<Settings> update){lock(gate){bool wasPaused=config.Paused,wasForce=config.AllowForceKill;update(config);if((wasPaused&&!config.Paused)||(!wasForce&&config.AllowForceKill&&state.Plan.ForceRequired)){if(config.AllowForceKill)state.Plan.ForceRequired=false;state.Plan.Resume(DateTime.UtcNow,config.RestartNoticeSeconds);Files.Save("state.json",state);}Files.Save("settings.json",config);}next=DateTime.MinValue;}
  public void Start(){Files.Log("桌面守护 2.6 启动");timer=new System.Threading.Timer(Tick,null,0,1000);}
  public void Restart(bool force){manualRestart=true;forceNow=force;next=DateTime.MinValue;}
  public void Diagnose(){probeRequested=true;next=DateTime.MinValue;}
  public bool Delay(){lock(gate){if(View.Mode=="正在应用代理"||String.IsNullOrEmpty(state.Plan.Proxy))return false;manualRestart=false;forceNow=false;state.Plan.Delay(DateTime.UtcNow);Files.Save("state.json",state);Files.Log("用户已将重启延后 10 分钟。");}next=DateTime.MinValue;return true;}
  public void Open(){try{var root=Native.Roots().FirstOrDefault();using(var p=Process.GetProcessById(root!=null?root.Pid:View.CodexPid)){if(p.MainWindowHandle!=IntPtr.Zero){Native.ShowWindow(p.MainWindowHandle,9);Native.SetForegroundWindow(p.MainWindowHandle);return;}}}catch{}openRequested=true;next=DateTime.MinValue;}
  Candidate Detect(Settings settings,out Health health){var seen=new HashSet<string>();health=new Health();foreach(var candidate in ProxyTools.Candidates(settings)){if(!seen.Add(candidate.Uri)||!ProxyTools.Tcp(candidate.Uri)||!ProxyTools.Connect(candidate.Uri))continue;Health previous;lock(gate){cached.TryGetValue(candidate.Uri,out previous);}health=previous??new Health{Tcp=true,Tunnel=true,CheckedUtc=""};bool force=probeRequested;probeRequested=false;if((force||previous==null||(DateTime.UtcNow-Files.Date(previous.CheckedUtc)).TotalSeconds>=settings.HealthCheckSeconds)&&Interlocked.CompareExchange(ref healthBusy,1,0)==0){string uri=candidate.Uri;ThreadPool.QueueUserWorkItem(x=>{try{var result=ProxyTools.Probe(uri);lock(gate){cached[uri]=result;}}catch{}finally{Interlocked.Exchange(ref healthBusy,0);}});}return candidate;}return null;}
  void Publish(string mode,string proxy,string source,string error,Health health){var view=new ViewState{UpdatedUtc=DateTime.UtcNow.ToString("o"),GuardPid=Process.GetCurrentProcess().Id,Mode=mode,ObservedProxy=proxy??"",AppliedProxy=state.AppliedProxy??"",Source=source??"",CodexPid=state.CodexPid,LastError=error??"",PendingSamples=samples,Health=health??new Health(),RestartDueUtc=state.Plan.DueUtc,ForceRequired=state.Plan.ForceRequired,RestartTicket=state.Plan.Ticket};View=view;lock(gate){Files.Save("state.json",state);}Files.Save("status.json",view);if(lastMode!=mode){Files.Log(mode+(String.IsNullOrEmpty(error)?"":"："+error));lastMode=mode;}}
  void Tick(object unused){if(disposed||DateTime.UtcNow<next||Interlocked.Exchange(ref busy,1)!=0)return;try{
   Settings settings=Config();if(settings.Paused){Publish("已暂停",View.ObservedProxy,View.Source,"",View.Health);next=DateTime.UtcNow.AddSeconds(10);return;}
   if(settings.PollSeconds<5||settings.StableSamples<2||settings.RestartCooldownSeconds<30||settings.RestartNoticeSeconds<10)throw new InvalidOperationException("守护时间配置无效。");
   Health health;var found=Detect(settings,out health);string seen=found==null?"":found.Uri,source=found==null?"":found.Source;string stable=ProxyTools.Stable(ref pending,ref samples,seen,settings.StableSamples),mode=found==null?"等待有效代理":"确认代理中";var roots=found==null?new List<RootProcess>():Native.Roots();if(stable==null&&found!=null&&(LaunchPolicy.FastStart(roots.Count>0,openRequested,settings.AutoStartCodex,manualRestart)||roots.Any(p=>LaunchPolicy.UsesProxy(p.Command,seen))))stable=seen;
   if(stable!=null){var adopted=roots.FirstOrDefault(p=>LaunchPolicy.UsesProxy(p.Command,stable));if(adopted!=null&&!manualRestart){state.CodexPid=adopted.Pid;state.CodexStartTicks=adopted.StartTicks;state.AppliedProxy=stable;state.Plan.Clear();}bool managed=roots.Any(p=>p.Pid==state.CodexPid&&p.StartTicks==state.CodexStartTicks&&LaunchPolicy.UsesProxy(p.Command,state.AppliedProxy));if(!manualRestart&&!managed)state.Plan.Clear();bool needs=LaunchPolicy.NeedsRestart(roots.Count>0,managed,stable==state.AppliedProxy,manualRestart,!String.IsNullOrEmpty(state.Plan.Proxy));bool start=roots.Count==0&&(settings.AutoStartCodex||openRequested||manualRestart),userLaunch=roots.Count==0&&openRequested;if(roots.Count>0&&!managed&&!manualRestart){state.CodexPid=roots[0].Pid;state.CodexStartTicks=roots[0].StartTicks;state.AppliedProxy="";}if(roots.Count==0){state.CodexPid=0;state.CodexStartTicks=0;}mode=roots.Count>0&&!managed?"手动启动 · 保留现有会话":"守护中";DateTime now=DateTime.UtcNow;state.RestartHistoryUtc=state.RestartHistoryUtc.Where(s=>(now-Files.Date(s)).TotalSeconds<settings.RestartWindowSeconds).ToList();
    if(needs||start){
     if(!userLaunch&&now<Files.Date(settings.NotBeforeUtc))mode="等待首次应用";
     else if(!manualRestart&&!userLaunch&&(now-Files.Date(state.LastRestartUtc)).TotalSeconds<settings.RestartCooldownSeconds)mode="等待重启间隔";
     else if(!manualRestart&&!userLaunch&&state.RestartHistoryUtc.Count>=settings.MaxRestartsPerWindow)mode="已限制频繁重启";
     else {
      lock(gate){if(roots.Count>0){state.Plan.Queue(stable,now,settings.RestartNoticeSeconds);if(manualRestart){state.Plan.DueUtc=now.ToString("o");if(forceNow)state.Plan.ForceRequired=false;}}}
      if(roots.Count>0&&state.Plan.ForceRequired&&!forceNow)mode="等待手动退出 Codex";
      else if(roots.Count>0&&!state.Plan.Ready(now))mode="准备重启 Codex";
      else {
       if(!ProxyTools.Connect(stable))throw new InvalidOperationException("新代理的最终验证失败，稍后重试。");string exe=Native.CodexExe();if(disposed)return;
       lock(gate){if(disposed||config.Paused||(roots.Count>0&&!manualRestart&&!state.Plan.Ready(DateTime.UtcNow)))return;Publish("正在应用代理",seen,source,"",health);}
       bool stopped=StopRoots(roots,settings.AllowForceKill||forceNow);
       if(!stopped){lock(gate){state.Plan.ForceRequired=true;}manualRestart=false;forceNow=false;mode="等待手动退出 Codex";Files.Log("Codex 未正常退出，保留进程。可延后、手动退出，或在窗口明确选择强制重启。");}
       else {if(disposed)return;state.LastRestartUtc=DateTime.UtcNow.ToString("o");state.RestartHistoryUtc.Add(state.LastRestartUtc);Files.Save("state.json",state);using(var p=Process.Start(ProxyTools.StartInfo(exe,stable,settings.MinimizeOnLaunch))){}RootProcess started=null;for(int attempt=0;attempt<20&&!disposed;attempt++){Thread.Sleep(1000);started=Native.Roots().FirstOrDefault(p=>LaunchPolicy.UsesProxy(p.Command,stable));if(started!=null)break;}if(started==null)throw new InvalidOperationException("Codex 尚未以指定代理启动，将自动重试。");state.AppliedProxy=stable;state.CodexPid=started.Pid;state.CodexStartTicks=started.StartTicks;state.Plan.Clear();manualRestart=false;forceNow=false;openRequested=false;Files.Log("Codex 已应用代理 "+stable+"，PID "+started.Pid);mode="守护中";}
      }
     }
    }else if(managed){lock(gate){state.Plan.Clear();}}
   }
   failures=0;Publish(mode,seen,source,"",health);double wait=settings.PollSeconds;if(mode=="准备重启 Codex")wait=Math.Min(wait,Math.Max(1,(Files.Date(state.Plan.DueUtc)-DateTime.UtcNow).TotalSeconds));next=DateTime.UtcNow.AddSeconds(wait);
  }catch(Exception error){failures++;int delay=Math.Min(60,10*(1<<Math.Min(3,failures-1)));Files.Log("检测异常，"+delay+" 秒后重试："+error.Message);try{Publish("异常重试",View.ObservedProxy,View.Source,error.Message,View.Health);}catch{}next=DateTime.UtcNow.AddSeconds(delay);}finally{Interlocked.Exchange(ref busy,0);}}
  public static bool CloseDesktop(Process process,bool force,int waitMs){try{if(process.HasExited)return true;process.CloseMainWindow();if(process.WaitForExit(waitMs))return true;if(!force)return false;process.Kill();return process.WaitForExit(5000);}catch(InvalidOperationException){return true;}}
  static bool StopRoots(List<RootProcess> roots,bool force){var all=Native.Processes();foreach(var root in roots){if(!Native.Identity(root))throw new InvalidOperationException("Codex 进程身份已变化，取消重启。");using(var process=Process.GetProcessById(root.Pid)){if(!CloseDesktop(process,force,15000))return false;}var tree=new HashSet<int>{root.Pid};bool changed;do{changed=false;foreach(var child in all)if(tree.Contains(child.Parent)&&tree.Add(child.Pid))changed=true;}while(changed);foreach(var child in all.Where(p=>p.Pid!=root.Pid&&tree.Contains(p.Pid)&&(p.Path.StartsWith(Path.GetDirectoryName(root.Path)+"\\",StringComparison.OrdinalIgnoreCase)||p.Path.StartsWith(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"OpenAI\Codex\"),StringComparison.OrdinalIgnoreCase))))if(Native.Identity(child))try{using(var p=Process.GetProcessById(child.Pid))p.Kill();}catch{}Thread.Sleep(2000);}return true;}
  public void ExitSession(){string session=Native.SessionKey();Update(c=>c.ExitSessionKey=session);Files.Log("用户退出本次登录的守护；登录自启动设置保持不变。");Dispose();}
  public void Dispose(){disposed=true;if(timer!=null)timer.Dispose();}
 }
 static class Startup {
  public const string TaskName="CodexProxyDesktop";
  static dynamic Folder(){dynamic scheduler=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));scheduler.Connect();return scheduler.GetFolder("\\");}
  public static bool Enabled(){try{dynamic task=Folder().GetTask(TaskName);return task.Enabled&&String.Equals((string)task.Definition.Actions.Item(1).Path,Program.Exe,StringComparison.OrdinalIgnoreCase);}catch{return false;}}
  public static void Set(bool enabled){dynamic scheduler=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));scheduler.Connect();dynamic folder=scheduler.GetFolder("\\");try{dynamic old=folder.GetTask(TaskName);if(!String.Equals((string)old.Definition.Actions.Item(1).Path,Program.Exe,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("同名任务属于其他程序。");if(!enabled){old.Enabled=false;return;}}catch(Exception e){if((uint)e.HResult!=0x80070002)throw;}if(!enabled)return;
   dynamic task=scheduler.NewTask(0);string sid=WindowsIdentity.GetCurrent().User.Value;task.RegistrationInfo.Description="Codex 代理管理器：静默登录启动、连接诊断、可延后的重启。";task.Principal.UserId=sid;task.Principal.LogonType=3;task.Principal.RunLevel=0;task.Settings.Enabled=true;task.Settings.Hidden=true;task.Settings.MultipleInstances=2;task.Settings.ExecutionTimeLimit="PT0S";task.Settings.DisallowStartIfOnBatteries=false;task.Settings.StopIfGoingOnBatteries=false;task.Settings.StartWhenAvailable=true;task.Settings.RestartInterval="PT1M";task.Settings.RestartCount=999;dynamic login=task.Triggers.Create(9);login.UserId=sid;login.Delay="PT3S";dynamic repeat=task.Triggers.Create(1);repeat.StartBoundary=DateTime.Now.AddMinutes(5).ToString("yyyy-MM-ddTHH:mm:ss");repeat.Repetition.Interval="PT5M";repeat.Repetition.StopAtDurationEnd=false;dynamic action=task.Actions.Create(0);action.Path=Program.Exe;action.Arguments="--background";action.WorkingDirectory=Program.Root;folder.RegisterTaskDefinition(TaskName,task,6,sid,null,3,null);
  }
  public static void Remove(){dynamic folder=Folder();try{dynamic task=folder.GetTask(TaskName);if(!String.Equals((string)task.Definition.Actions.Item(1).Path,Program.Exe,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("同名任务属于其他程序。");task.Enabled=false;folder.DeleteTask(TaskName,0);}catch(Exception e){if((uint)e.HResult!=0x80070002)throw;}}
  public static void Shortcut(){dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));dynamic link=shell.CreateShortcut(Program.Link);link.TargetPath=Program.Exe;link.WorkingDirectory=Program.Root;link.Description="打开 Codex 代理管理器";link.IconLocation=Program.Exe+",0";link.Save();}
  public static void ProxyShortcut(){string menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),"Programs");Directory.CreateDirectory(menu);dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));foreach(string name in new[]{"ChatGPT（代理启动）.lnk","ChatGPT.lnk"}){string path=Path.Combine(menu,name);if(name=="ChatGPT.lnk"&&!File.Exists(path))continue;dynamic link=shell.CreateShortcut(path);if(name=="ChatGPT.lnk"&&!LaunchPolicy.IsCodexTarget((string)link.TargetPath)&&!String.Equals((string)link.TargetPath,Program.Exe,StringComparison.OrdinalIgnoreCase))continue;link.TargetPath=Program.Exe;link.Arguments="--open-codex";link.WorkingDirectory=Program.Root;link.Description="通过代理管理器打开 ChatGPT / Codex，已有会话直接唤起";link.IconLocation=Native.CodexExe()+",0";link.Save();}}
  public static void RestoreProxyShortcut(){string menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),"Programs");dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));foreach(string name in new[]{"ChatGPT（代理启动）.lnk","ChatGPT.lnk"}){string path=Path.Combine(menu,name);if(!File.Exists(path))continue;dynamic link=shell.CreateShortcut(path);if(!String.Equals((string)link.TargetPath,Program.Exe,StringComparison.OrdinalIgnoreCase)||((string)link.Arguments)!="--open-codex")continue;if(name=="ChatGPT（代理启动）.lnk")File.Delete(path);else{link.TargetPath=Native.CodexExe();link.Arguments="";link.IconLocation=Native.CodexExe()+",0";link.Save();}}}
 }
